"""The bot's signals and prices must reproduce the research code exactly (fixtures were generated by the sprint's own core/engine/tournament code)."""
import csv, json, os
import numpy as np
from bot import indicators, rules, model

FX = os.path.join(os.path.dirname(__file__), "fixtures")


def _spy():
    rows = list(csv.DictReader(open(os.path.join(FX, "SPY_daily.csv"))))
    return {"date": [r["date"] for r in rows], **{k: np.array([float(r[n]) for r in rows]) for k, n in (("o", "open"), ("h", "high"), ("l", "low"), ("c", "close"))}}


def _exp():
    return list(csv.DictReader(open(os.path.join(FX, "expected_signals.csv"))))


def test_indicators_and_signals_match_research_on_every_day():
    bars = _spy()
    ind = indicators.compute(bars)
    sig = rules.rule_signals(ind)
    pos = {d: i for i, d in enumerate(bars["date"])}
    exp = _exp()
    assert len(exp) > 8000
    bad = {"S1": 0, "K1": 0, "K2": 0, "K3": 0, "K4": 0}
    maxdiff = 0.0
    for r in exp:
        i = pos[r["date"]]
        for k in bad:
            if bool(int(r[k])) != bool(sig[k][i]):
                bad[k] += 1
        for name, key in (("ibs", "ibs"), ("rsi", "rsi"), ("dem", "dem"), ("sma50", "sma50")):
            a, b = float(r[name]), ind[key][i]
            if not (np.isnan(a) and np.isnan(b)):
                maxdiff = max(maxdiff, abs(a - b))
    assert bad == {"S1": 0, "K1": 0, "K2": 0, "K3": 0, "K4": 0}
    assert maxdiff < 1e-9


def test_five_year_window_gives_same_todays_signal():
    """Live bot fetches 5 years, not the full history; Wilder RSI seeds differently but must converge before the last bar."""
    bars = _spy()
    full = indicators.compute(bars)
    n = 1255
    cut = {k: v[-n:] for k, v in bars.items()}
    short = indicators.compute(cut)
    for key in ("rsi", "dem", "ibs", "sma50"):
        assert abs(full[key][-1] - short[key][-1]) < 1e-6
    sf, ss = rules.rule_signals(full), rules.rule_signals(short)
    last = 600     # compare the last 600 bars of signals
    for k in sf:
        assert (sf[k][-last:] == ss[k][-last:]).all()


def test_schedule_trade_counts_match_research_per_year():
    """Research (kelly table, 2014-2026): S1 37.0 trades a year, K1 38.8, K2 21.7, K3 9.3 (the Kelly row counts only days with a priced contract)."""
    bars = _spy()
    ind = indicators.compute(bars)
    sig = rules.rule_signals(ind)
    dates = np.array(bars["date"])
    m = dates >= "2014-01-01"
    yrs = m.sum() / 252
    for r in rules.RULES:
        keep = rules.schedule(sig[r.id], r.hold)
        per_year = keep[m].sum() / yrs
        assert abs(per_year - r.per_year) / r.per_year < 0.06, (r.id, per_year, r.per_year)


def test_model_price_matches_engine_to_1e9():
    fx = json.load(open(os.path.join(FX, "model_parity.json")))
    worst = 0.0
    for x in fx:
        vols = dict(v1=x["v1"], v9=x["v9"], v30=x["v30"], v93=x["v93"])
        p = model.price_call(x["S"], x["K"], x["sess"], vols, x["carry"])
        worst = max(worst, abs(p - x["prem"]))
        k = model.strike_for_delta(x["S"], x["delta"], x["sess"], vols, x["carry"])
        assert k == x["K"], (x["date"], x["delta"], k, x["K"])
    assert worst < 1e-9, worst
